// Extension d'essai des fichiers (protocole 1.0, lot 7) : importer des points, exporter un relevé.
planche.sur("commande.importer-points", async (d) => {
  const en = d && d.langue === "en";
  const fichier = await planche.fichiers.ouvrir([".csv", ".txt"]);
  if (fichier === null) {
    await planche.message.afficher(en ? "No file chosen." : "Aucun fichier choisi.", "alerte");
    return null;
  }
  // Une ligne par point : x;y;z en mètres. Les lignes illisibles sont ignorées.
  const points = fichier.texte.split(/\r?\n/).map((l) => l.split(";").map((v) => Number(v.replace(",", ".")))).filter((p) => p.length === 3 && p.every((v) => Number.isFinite(v)));
  if (points.length < 2) {
    await planche.message.afficher((en ? "No polyline in " : "Aucun tracé dans ") + fichier.nom, "alerte");
    return 0;
  }
  await planche.operation.ouvrir(en ? "Import points" : "Importer des points");
  for (let i = 1; i < points.length; i++) await planche.modele.ligne(points[i - 1], points[i]);
  await planche.operation.valider();
  await planche.message.afficher(points.length + (en ? " points imported from " : " points repris de ") + fichier.nom);
  return points.length;
});

planche.sur("commande.exporter-releve", async (d) => {
  const en = d && d.langue === "en";
  const m = await planche.modele.lire();
  const texte = (en ? "Kind;Count" : "Nature;Nombre") + "\n" + (en ? "Faces" : "Faces") + ";" + m.faces.length + "\n" + (en ? "Edges" : "Arêtes") + ";" + m.aretes.length + "\n" + (en ? "Objects" : "Objets") + ";" + m.objets.length + "\n";
  const fait = await planche.fichiers.enregistrer(en ? "drawing-count.csv" : "releve-du-dessin.csv", texte);
  await planche.message.afficher(fait ? (en ? "File saved." : "Fichier enregistré.") : en ? "Saving cancelled." : "Enregistrement annulé.", fait ? "info" : "alerte");
  return fait;
});
